def split_sequence(n, a):
    increasing = []
    decreasing = []
    transition_points = []

    # Identify potential transition points
    for i in range(1, n):
        if a[i] <= a[i - 1]:
            transition_points.append(i)

    # If there are more than one transition points, it's impossible to split
    if len(transition_points) > 1:
        return "NO"

    # If there are no transition points, check if the entire sequence is increasing or decreasing
    if not transition_points:
        if all(a[i] >= a[i - 1] for i in range(1, n)):
            return "YES\n" + ' '.join('0' for _ in range(n))
        elif all(a[i] <= a[i - 1] for i in range(1, n)):
            return "YES\n" + ' '.join('1' for _ in range(n))
        else:
            return "NO"

    # Split the sequence at the identified transition point
    transition_point = transition_points[0]
    increasing = a[:transition_point]
    decreasing = a[transition_point:]

    # Verify the split
    if all(increasing[i] < increasing[i - 1] for i in range(1, len(increasing))):
        if all(decreasing[i] > decreasing[i - 1] for i in range(1, len(decreasing))):
            return "YES\n" + ' '.join('0' if x in increasing else '1' for x in a)

    return "NO"

