def split_sequence(n, a):
    # Initialize variables to store the lengths of the longest increasing and decreasing subsequences
    max_increasing = [1] * n
    max_decreasing = [1] * n

    # Calculate the length of the longest increasing subsequence ending at each position
    for i in range(1, n):
        if a[i] > a[i - 1]:
            max_increasing[i] = max_increasing[i - 1] + 1

    # Calculate the length of the longest decreasing subsequence starting at each position
    for i in range(n - 2, -1, -1):
        if a[i] > a[i + 1]:
            max_decreasing[i] = max_decreasing[i + 1] + 1

    # Find the split point where the increasing and decreasing subsequences meet
    for i in range(n - 1):
        if max_increasing[i] + max_decreasing[i + 1] == n:
            # Mark elements before the split point as part of the increasing sequence
            # and elements after the split point as part of the decreasing sequence
            result = [0] * n
            for j in range(i + 1):
                result[j] = 0
            for j in range(i + 1, n):
                result[j] = 1
            return "YES\n" + ' '.join(map(str, result))

    # If no valid split point is found, return "NO"
    return "NO"

